@startuml

class ProjectManager {
  + name : string
}

class Project {
  + startDate : date
  + endDate : date
  + initiate() : void
  + terminate() : void
}

class Team {
}

class WorkProduct {
  + description : string
  + percentComplete : float
  + validate() : void
}

class Requirement extends WorkProduct {
  + media : string
  + validate() : void
  + publish() : void
}

class System extends WorkProduct {
  + platform : string
  + validate() : void
}

ProjectManager "1" -- "1" Project : leads
ProjectManager "1" -- "1" Team : leads
Project "1" -- "1" Team : executes
Project "1" -- "1..*" Requirement : uses
Project "1" -- "1..*" System : produces

@enduml

